#[cfg(test)]
mod tests {
    use super::*;

    /// This string goes straight into a `d=` attribute in a page the gateway writes, so the two
    /// things worth pinning are that it is a path at all and that it cannot end the attribute.
    #[test]
    fn the_mark_is_a_closed_path_that_cannot_escape_its_attribute() {
        assert!(MARK_PATH_D.starts_with("M "), "a path starts with a move");
        assert!(MARK_PATH_D.trim_end().ends_with('Z'), "the mark is one closed subpath");
        assert!(!MARK_PATH_D.contains('"'), "a quote would end the d= attribute early");
        assert!(!MARK_PATH_D.contains('<'), "a < would end the tag early");
        assert_eq!(MARK_VIEWBOX, "0 0 1024 1024");
        // Big enough to be the generated mark rather than a placeholder left behind.
        assert!(MARK_PATH_D.len() > 10_000, "that is not the generated mark");
    }
}
